"""
Entered vs calculated comparison
--------------------------------
The entered degrees remain authoritative. This module only reports how far
the ephemeris-calculated positions differ, which makes data-entry errors
(wrong sign, transposed minutes, wrong time zone) easy to spot.
"""

# Generated by GitHub Copilot - Sep-27-2026

from __future__ import annotations

from dataclasses import dataclass

from .input_model import BODY_KEYS, LAGNA_KEY, EnteredPosition
from .planets import JyotishChart

# Deltas above this (in degrees) are flagged for review.
DEFAULT_TOLERANCE_DEG = 1.0


@dataclass
class Difference:
    body: str
    entered: float
    calculated: float
    delta: float            # signed, shortest arc: entered - calculated
    sign_mismatch: bool
    flagged: bool

    @property
    def delta_dm(self) -> str:
        magnitude = abs(self.delta)
        d = int(magnitude)
        m = int(round((magnitude - d) * 60))
        if m == 60:
            d, m = d + 1, 0
        sign = "+" if self.delta >= 0 else "-"
        return f"{sign}{d:02d}° {m:02d}'"


def _shortest_arc(a: float, b: float) -> float:
    """Signed difference a - b reduced to (-180, +180]."""
    diff = (a - b) % 360.0
    return diff - 360.0 if diff > 180.0 else diff


def compare(entered: dict[str, EnteredPosition], calculated: JyotishChart,
            tolerance_deg: float = DEFAULT_TOLERANCE_DEG) -> list[Difference]:
    """Compare each entered position against the calculated chart."""
    results: list[Difference] = []
    for body in BODY_KEYS:
        pos = entered.get(body)
        if pos is None:
            continue
        if body == LAGNA_KEY:
            calc_lon = calculated.lagna.longitude
            calc_sign = calculated.lagna.rashi_index
        elif body in calculated.planets:
            calc_lon = calculated.planets[body].longitude
            calc_sign = calculated.planets[body].rashi_index
        else:
            continue
        delta = _shortest_arc(pos.longitude, calc_lon)
        sign_mismatch = pos.rashi_index != calc_sign
        results.append(Difference(
            body=body,
            entered=pos.longitude,
            calculated=calc_lon,
            delta=delta,
            sign_mismatch=sign_mismatch,
            flagged=sign_mismatch or abs(delta) > tolerance_deg,
        ))
    return results


def format_comparison(diffs: list[Difference],
                      tolerance_deg: float = DEFAULT_TOLERANCE_DEG) -> str:
    """Render the comparison table. Purely informational — nothing is overwritten."""
    lines = [
        "",
        "═" * 74,
        "  ENTERED vs CALCULATED  (entered degrees remain authoritative)",
        "═" * 74,
        f"  {'Body':<10} {'Entered':>11}  {'Calculated':>11}  {'Delta':>10}  Review",
        "  " + "─" * 70,
    ]
    for d in diffs:
        note = ""
        if d.sign_mismatch:
            note = "⚠ different rashi"
        elif d.flagged:
            note = f"⚠ > {tolerance_deg:g}°"
        lines.append(f"  {d.body:<10} {d.entered:>10.4f}°  {d.calculated:>10.4f}°  "
                     f"{d.delta_dm:>10}  {note}")

    flagged = [d.body for d in diffs if d.flagged]
    lines.append("  " + "─" * 70)
    if flagged:
        lines.append(f"  {len(flagged)} position(s) to review: {', '.join(flagged)}")
        lines.append("  Check birth time, time zone and ayanamsha before trusting either side.")
    else:
        lines.append("  All entered positions agree with the calculation within tolerance.")
    lines.append("  Note: the built-in ephemeris is approximate; entered degrees win.")
    lines.append("")
    return "\n".join(lines)
